class Table:
    def __init__(self, name: str, schema: list[str]):
        self.name = name
        self.schema = schema
        self.rows: list[dict] = []

    def insert(self, **kwargs) -> None:
        self.rows.append(kwargs)

    def select(self, fields: list[str], where: dict | None = None) -> list[dict]:
        matched = []
        for r in self.rows:
            if where and any(r.get(k) != v for k, v in where.items()):
                continue
            matched.append({f: r.get(f) for f in fields})
        return matched
